<template>
  <ViewShell title="消息通知" :tag="`${unreadCount} 条未读`" :icon="BellOutlined">
    <section class="view-card notification-panel"><div class="notification-toolbar"><div><h2 class="view-card__title"><BellOutlined /> 运行消息</h2><p>水情告警、闸门动作和平台事件会集中显示在这里。</p></div><div class="notification-actions"><select v-model="levelFilter"><option value="all">全部级别</option><option value="3">严重</option><option value="2">警告</option><option value="1">提示</option></select><button type="button" :disabled="!unreadCount" @click="readAll">全部标记已读</button><button v-if="canManage" type="button" class="primary-btn" @click="createOpen = true">发布通知</button></div></div><div v-if="error" class="manage-error" role="alert">{{ error }}</div><ul class="notification-list"><li v-for="item in filteredMessages" :key="item.id" :class="{ 'is-unread': !item.read }"><div class="notice-icon" :class="`level-${item.level}`"><WarningOutlined v-if="item.level >= 2" /><InfoCircleOutlined v-else /></div><div class="notice-content"><div class="notice-head"><strong>{{ item.type || '平台通知' }}</strong><span>{{ formatTime(item.createTime) }}</span></div><p>{{ item.content }}</p><div class="notice-foot"><span :class="`notice-level level-text-${item.level}`">{{ levelText(item.level) }}</span><button v-if="!item.read" type="button" @click="readOne(item)">标记已读</button><button v-if="canManage" type="button" class="danger-link" @click="remove(item)">删除</button></div></div></li><li v-if="!filteredMessages.length" class="manage-empty">暂无通知</li></ul></section>
    <div v-if="createOpen" class="modal-backdrop" @click.self="createOpen = false"><form class="manage-modal" @submit.prevent="publish"><div class="modal-head"><div><h2>发布平台通知</h2><p>通知将保存到 MySQL，并展示给值守人员。</p></div><button type="button" class="close-btn" aria-label="关闭" @click="createOpen = false">×</button></div><div class="form-grid"><label>通知类型<input v-model.trim="draft.type" maxlength="50" required placeholder="例如：设备维护" /></label><label>通知级别<select v-model.number="draft.level"><option :value="1">提示</option><option :value="2">警告</option><option :value="3">严重</option></select></label><label class="span-2">通知内容<textarea v-model.trim="draft.content" maxlength="1000" rows="4" required placeholder="填写需要告知值守人员的内容"></textarea></label></div><div class="modal-foot"><button type="button" class="plain-btn" @click="createOpen = false">取消</button><button class="primary-btn" type="submit" :disabled="saving">{{ saving ? '发布中…' : '确认发布' }}</button></div></form></div>
  </ViewShell>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { BellOutlined, InfoCircleOutlined, WarningOutlined } from '@ant-design/icons-vue'
import ViewShell from './ViewShell.vue'
import { addMessage, deleteMessage, listMessages, markAllMessagesRead, markMessageRead } from '../api/manageApi.js'
const level = Number(localStorage.getItem('level') ?? 1)
const canManage = level === 0 || level >= 3
const messages = ref([]); const levelFilter = ref('all'); const error = ref(''); const createOpen = ref(false); const saving = ref(false)
const draft = reactive({ type: '', level: 1, content: '' })
const filteredMessages = computed(() => messages.value.filter((item) => levelFilter.value === 'all' || String(item.level) === levelFilter.value))
const unreadCount = computed(() => messages.value.filter((item) => !item.read).length)
const levelText = (level) => ({ 3: '严重', 2: '警告', 1: '提示' }[level] || '通知')
const formatTime = (value) => value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '刚刚'
async function load() { try { messages.value = await listMessages() } catch (e) { error.value = e.message } }
async function readOne(item) { try { await markMessageRead(item.id); item.read = true } catch (e) { error.value = e.message } }
async function readAll() { try { await markAllMessagesRead(); messages.value.forEach((item) => { item.read = true }) } catch (e) { error.value = e.message } }
async function remove(item) { try { await deleteMessage(item.id); messages.value = messages.value.filter((row) => row.id !== item.id) } catch (e) { error.value = e.message } }
async function publish() { error.value = ''; saving.value = true; try { await addMessage(draft); draft.type = ''; draft.level = 1; draft.content = ''; createOpen.value = false; await load() } catch (e) { error.value = e.message } finally { saving.value = false } }
onMounted(load)
</script>

<style scoped>
.notification-panel{min-height:100%}.notification-toolbar{display:flex;justify-content:space-between;align-items:flex-start;gap:18px}.notification-toolbar p{margin:-8px 0 18px;color:#7890a4;font-size:11px}.notification-actions{display:flex;gap:8px;flex-wrap:wrap}.notification-actions select,.notification-actions button{height:32px;padding:0 10px;border:1px solid #dce8f0;border-radius:7px;background:#fff;color:#557188;font-size:11px}.notification-actions button{cursor:pointer}.notification-actions button:disabled{cursor:not-allowed;opacity:.5}.notification-actions .primary-btn{border-color:#1679d1;background:#1679d1;color:#fff}.manage-error{margin:10px 0;padding:10px 12px;border-radius:8px;background:#fff2f1;color:#b64c4a;font-size:12px}.notification-list{display:flex;flex-direction:column;gap:9px;margin:0;padding:0;list-style:none}.notification-list>li:not(.manage-empty){display:flex;gap:12px;padding:14px;border:1px solid #e7eff4;border-radius:11px;background:#fbfdfe}.notification-list>li.is-unread{border-color:#cfe6f5;background:#f8fcff}.notice-icon{display:flex;align-items:center;justify-content:center;flex:0 0 31px;height:31px;border-radius:9px;font-size:15px}.notice-icon.level-3{background:#fff0ee;color:#d5574f}.notice-icon.level-2{background:#fff6e7;color:#d29133}.notice-icon.level-1{background:#eaf6ff;color:#2685c5}.notice-content{min-width:0;flex:1}.notice-head{display:flex;justify-content:space-between;gap:12px}.notice-head strong{color:#2d506c;font-size:12px}.notice-head span{color:#91a3b0;font-size:10px}.notice-content p{margin:5px 0 10px;color:#637d91;font-size:12px;line-height:1.7}.notice-foot{display:flex;align-items:center;gap:11px}.notice-foot button{border:0;background:none;color:#2680bf;font-size:10px;cursor:pointer}.notice-foot .danger-link{color:#d06462}.notice-level{padding:2px 7px;border-radius:5px;font-size:10px}.level-text-3{background:#fff0ee;color:#cb5049}.level-text-2{background:#fff5e5;color:#b97922}.level-text-1{background:#eaf5ff;color:#267db8}.manage-empty{text-align:center;color:#91a4b2;padding:28px!important;display:block!important}.modal-backdrop{position:fixed;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(9,35,58,.4)}.manage-modal{width:min(560px,100%);padding:22px;border-radius:15px;background:#fff;box-shadow:0 20px 60px rgba(13,53,82,.25)}.modal-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.modal-head h2{margin:0;color:#173955;font-size:18px}.modal-head p{margin:4px 0 0;color:#8298a9;font-size:11px}.close-btn{border:0;background:none;color:#8197a7;font-size:24px;cursor:pointer}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.form-grid label{display:flex;flex-direction:column;gap:5px;color:#617b90;font-size:11px}.form-grid input,.form-grid select,.form-grid textarea{border:1px solid #dce8f0;border-radius:8px;background:#fbfdfe;color:#284967;font:inherit;font-size:12px;outline:none}.form-grid input,.form-grid select{height:35px;padding:0 9px}.form-grid textarea{padding:8px;resize:vertical}.span-2{grid-column:span 2}.modal-foot{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}.primary-btn,.plain-btn{height:34px;padding:0 14px;border-radius:8px;font-size:12px;cursor:pointer}.primary-btn{border:0;background:#1679d1;color:#fff}.plain-btn{border:1px solid #d8e5ee;background:#fff;color:#557188}@media(max-width:650px){.notification-toolbar{flex-direction:column}.notification-actions{width:100%}.notification-actions select{flex:1}.notice-head{flex-direction:column;gap:2px}.form-grid{grid-template-columns:1fr}.span-2{grid-column:auto}}
</style>
